-- Read-only, prior games only. Observed order is not a target pregame announcement.
with first_pa as (select game_year season,game_pk,game_date,case when inning_topbot='Top' then source_away_team else source_home_team end team,coalesce(mlbam_batter_id,source_batter_id) batter,min(at_bat_number) first_ab from pick2_raw_mlb_statcast_pitches where game_year=2025 and game_type='R' and game_date between '2025-03-11' and '2025-08-30' group by 1,2,3,4,5), ranked as(select *,row_number() over(partition by season,game_pk,team order by first_ab,batter) batting_order from first_pa),r as(select * from ranked where batting_order<=9),c as(select * from mlb_ml_xyear_lineup_v1 where season=2025 and game_date between '2025-03-11' and '2025-08-30') select count(*) checked,count(*) filter(where r.game_pk is null) missing_raw,count(*) filter(where c.game_pk is null) missing_canonical,count(*) filter(where r.batting_order<>c.batting_order) order_mismatch from r full join c using(season,game_pk,game_date,team,batter)
